def calculate_S(x, y, z, a, b, c):
    """Calculates the output S for a given triple (x, y, z) and query (a, b, c)."""
    D1 = x + y - a - b
    D2 = y + z - b - c
    D3 = z + x - c - a
    S = abs(D1) + abs(D2) + abs(D3)
    return S

# Test query Q2 = (0, 9, 9)
a, b, c = 0, 9, 9
